const raw = $input.first().json.body;
let payload;
try { payload = typeof raw === 'string' ? JSON.parse(raw.trim()) : raw; } catch (error) { throw new Error('JSON V2 inválido: ' + error.message); }
if (!payload || typeof payload !== 'object' || Array.isArray(payload)) throw new Error('O provisionamento deve ser um objeto JSON.');
const required = (value, field) => { if (value === undefined || value === null || String(value).trim() === '') throw new Error('Campo obrigatório: ' + field); return value; };
const email = (value, field) => { const result = String(required(value, field)).trim().toLowerCase(); if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(result)) throw new Error('E-mail inválido: ' + field); return result; };
const numeroPositivo = (value, field) => { const n = Number(value); if (!Number.isFinite(n) || n <= 0) throw new Error('Campo numérico inválido (deve ser um número maior que zero): ' + field); return n; };
required(payload.empresa?.codigo, 'empresa.codigo');
required(payload.empresa?.nome_fantasia, 'empresa.nome_fantasia');
required(payload.empresa?.whatsapp_numero, 'empresa.whatsapp_numero');
required(payload.empresa?.instancia_evolution, 'empresa.instancia_evolution');
if (!['solo', 'equipe', 'empresa'].includes(String(payload.plano_codigo || '').toLowerCase())) throw new Error('plano_codigo deve ser solo, equipe ou empresa.');
required(payload.admin?.nome, 'admin.nome');
payload.admin.email = email(payload.admin?.email, 'admin.email');
if (!Array.isArray(payload.profissionais) || payload.profissionais.length === 0) throw new Error('Informe ao menos um profissional.');
if (!Array.isArray(payload.servicos) || payload.servicos.length === 0) throw new Error('Informe ao menos um serviço.');
const authAccounts = [{ chave: 'admin', tipo: 'administrador', nome: String(payload.admin.nome).trim(), email: payload.admin.email }];
const profissionalKeys = new Set();
for (const p of payload.profissionais) {
  required(p.chave, 'profissionais[].chave');
  required(p.nome, 'profissionais[].nome');
  const chave = String(p.chave);
  if (profissionalKeys.has(chave)) throw new Error('Chave de profissional repetida: ' + chave);
  profissionalKeys.add(chave);
  if (p.eh_admin !== undefined && typeof p.eh_admin !== 'boolean') throw new Error('eh_admin deve ser booleano.');
  p.eh_admin = p.eh_admin === true;
  if (p.eh_admin && p.email && String(p.email).trim().toLowerCase() !== payload.admin.email) throw new Error('O profissional administrador deve usar o e-mail do administrador.');
  p.acesso_portal = !p.eh_admin && p.acesso_portal === true;
  delete p.usuario_id;
  if (p.acesso_portal) {
    p.email = email(p.email, 'profissionais[].email quando acesso_portal for true');
    authAccounts.push({ chave: 'profissional:' + chave, tipo: 'profissional', nome: String(p.nome).trim(), email: p.email });
  }
}
if (payload.profissionais.filter(p => p.eh_admin).length > 1) throw new Error('Somente um profissional pode estar vinculado ao administrador.');
if (payload.recepcionistas === undefined) payload.recepcionistas = [];
if (!Array.isArray(payload.recepcionistas)) throw new Error('recepcionistas deve ser uma lista.');
const recepcionistaKeys = new Set();
for (const r of payload.recepcionistas) {
  required(r.chave, 'recepcionistas[].chave');
  required(r.nome, 'recepcionistas[].nome');
  const chave = String(r.chave);
  if (recepcionistaKeys.has(chave)) throw new Error('Chave de recepcionista repetida: ' + chave);
  recepcionistaKeys.add(chave);
  r.email = email(r.email, 'recepcionistas[].email');
  r.papel = 'recepcionista';
  r.acesso_portal = true;
  delete r.usuario_id;
  authAccounts.push({ chave: 'recepcionista:' + chave, tipo: 'recepcionista', nome: String(r.nome).trim(), email: r.email });
}
const emails = authAccounts.map((account) => account.email);
if (new Set(emails).size !== emails.length) throw new Error('Cada acesso do portal deve ter um e-mail diferente.');
const servicoKeys = new Set();
for (const s of payload.servicos) {
  required(s.chave, 'servicos[].chave');
  required(s.nome, 'servicos[].nome');
  const chave = String(s.chave);
  if (servicoKeys.has(chave)) throw new Error('Chave de serviço repetida: ' + chave);
  servicoKeys.add(chave);
  s.duracao_min = numeroPositivo(s.duracao_min, 'servicos[].duracao_min');
  s.preco = numeroPositivo(s.preco, 'servicos[].preco');
  if (s.prazo_reativacao_dias != null || s.prazo_reativacao_meses != null || s.reativacao_objetivo != null) {
    const dias = s.prazo_reativacao_dias;
    const meses = s.prazo_reativacao_meses;
    if ((dias != null) === (meses != null)) throw new Error('Cada serviço deve ter prazo em dias OU meses.');
    const valor = dias ?? meses;
    if (!Number.isInteger(valor) || valor < 1 || valor > (meses != null ? 1200 : 32767)) throw new Error('Prazo de reativação deve ser inteiro e positivo.');
    if (!['manutencao', 'novo_servico'].includes(s.reativacao_objetivo)) throw new Error('Reativação deve sugerir manutenção ou novo serviço.');
  }
}
if (!Array.isArray(payload.profissional_servicos) || payload.profissional_servicos.length === 0) throw new Error('Informe os vínculos profissional_servicos.');
for (const [i, v] of payload.profissional_servicos.entries()) {
  if (!profissionalKeys.has(String(v.profissional_chave))) throw new Error('profissional_servicos[' + i + '].profissional_chave não corresponde a nenhum profissional cadastrado: ' + v.profissional_chave);
  if (!servicoKeys.has(String(v.servico_chave))) throw new Error('profissional_servicos[' + i + '].servico_chave não corresponde a nenhum serviço cadastrado: ' + v.servico_chave);
}
// Validar os períodos semanais antes de qualquer criação de conta Auth.
const horarioSegundos = (value, field) => {
  if (typeof value !== 'string' || !/^(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d)?$/.test(value)) throw new Error(field + ' deve ser horário válido HH:mm ou HH:mm:ss.');
  const [h, m, s = 0] = value.split(':').map(Number);
  return h * 3600 + m * 60 + s;
};
const intervaloSemanal = (h, field) => {
  if (!h || typeof h !== 'object' || Array.isArray(h)) throw new Error(field + ' deve ser objeto.');
  if (!Number.isInteger(h.dia_semana) || h.dia_semana < 0 || h.dia_semana > 6) throw new Error(field + '.dia_semana deve ser inteiro de 0 (domingo) a 6 (sábado).');
  if (typeof h.ativo !== 'boolean') throw new Error(field + '.ativo deve ser booleano.');
  const inicio = horarioSegundos(h.inicio, field + '.inicio');
  const fim = horarioSegundos(h.fim, field + '.fim');
  if (inicio >= fim) throw new Error(field + ': o fim deve ser posterior ao início; turnos pela meia-noite não são aceitos.');
  return {dia: h.dia_semana, inicio, fim, ativo: h.ativo};
};
if (!Array.isArray(payload.horarios_empresa) || payload.horarios_empresa.length === 0) throw new Error('Informe horarios_empresa.');
const expediente = payload.horarios_empresa.map((h, i) => intervaloSemanal(h, 'horarios_empresa[' + i + ']'));
if (!expediente.some(h => h.ativo)) throw new Error('A empresa precisa ter ao menos um período semanal ativo.');
if (!Array.isArray(payload.horarios_profissionais) || payload.horarios_profissionais.length === 0) throw new Error('Informe horarios_profissionais.');
const horariosPorProfissional = new Map();
let horariosAtivos = 0;
for (const [i, h] of payload.horarios_profissionais.entries()) {
  const field = 'horarios_profissionais[' + i + ']';
  const chave = String(h?.profissional_chave ?? '');
  if (!profissionalKeys.has(chave)) throw new Error(field + '.profissional_chave não corresponde a nenhum profissional cadastrado: ' + chave);
  const periodo = intervaloSemanal(h, field);
  if (!periodo.ativo) continue;
  horariosAtivos++;
  if (!expediente.some(e => e.ativo && e.dia === periodo.dia && e.inicio <= periodo.inicio && e.fim >= periodo.fim)) {
    throw new Error(field + ': horário ativo fora de um único período empresarial ativo ou atravessando uma pausa.');
  }
  const chaveDia = chave + ':' + periodo.dia;
  const anteriores = horariosPorProfissional.get(chaveDia) || [];
  if (anteriores.some(outro => periodo.inicio < outro.fim && outro.inicio < periodo.fim)) {
    throw new Error(field + ': sobreposição de horários ativos do mesmo profissional; horários adjacentes são permitidos.');
  }
  anteriores.push(periodo);
  horariosPorProfissional.set(chaveDia, anteriores);
}
if (!horariosAtivos) throw new Error('Informe ao menos um período semanal ativo de profissional.');
payload.plano_codigo = String(payload.plano_codigo).toLowerCase();
payload.empresa.codigo = String(payload.empresa.codigo).trim().toLowerCase();
payload.empresa.instancia_evolution = String(payload.empresa.instancia_evolution).trim().toLowerCase();
const redirectTo = payload.portal_redirect_url ? String(payload.portal_redirect_url).trim() : undefined;
delete payload.admin.usuario_id;
if (redirectTo && !/^https:\/\/[^\s]+$/i.test(redirectTo)) throw new Error('portal_redirect_url deve ser uma URL HTTPS.');
return [{ json: { payload, auth_accounts: authAccounts, redirect_to: redirectTo } }];

const source = $('Validar JSON V2').first().json;
const resposta = $input.first().json;
if (resposta.error || !(Number(resposta.statusCode)>=200 && Number(resposta.statusCode)<300)) {
 const b=resposta.body||{};
 throw new Error('Conferência pela API falhou. HTTP '+(resposta.statusCode||'sem resposta')+': '+(b.message||b.msg||resposta.error?.message||JSON.stringify(b))+' '+(b.details||'')+' '+(b.hint||''));
}
const db = resposta.body;
if (!Array.isArray(db.usuarios) || !Array.isArray(db.empresas)) throw new Error('Consulta de conferência retornou formato inesperado. Nenhuma conta foi criada.');
if (db.empresas.length) throw new Error('Empresa já encontrada por código, WhatsApp ou instância. Nenhum dado foi alterado. Conferir cadastro existente antes de repetir: ' + JSON.stringify(db.empresas));
// Política geral: reaproveitar apenas usuário Auth comprovadamente criado
// para a mesma empresa e mesma chave de acesso, sem vínculos ativos.
const accounts = source.auth_accounts.map(account => {
 const found = db.usuarios.filter(u => String(u.email).toLowerCase() === account.email);
 if (found.length > 1) throw new Error('Mais de uma conta encontrada: ' + account.email);
 const user = found[0];
 if (!user) return {...account, criado_nesta_execucao: true};
 if (user.operador || user.membros.length) throw new Error('Conta já vinculada: ' + account.email + '. Conferir vínculo antes de reutilizar.');
 const codigo = source.payload.empresa.codigo;
 const marker = user.app_metadata?.agenda24h_provisionamento;
 const trusted = [8,9,10,11,12,13].includes(marker?.versao) && marker.empresa_codigo === codigo && marker.chave === account.chave;
 if (!trusted) throw new Error('Conta preexistente sem marcador Auth validado para esta empresa e chave: ' + account.email + '. Não será alterada nem vinculada automaticamente; contas legadas sem marcador exigem reconciliação manual segura.');
 return {...account, usuario_id: user.id, criado_nesta_execucao: false};
});
return [{json:{...source, auth_accounts:accounts}}];

const source=$input.first().json;
return source.auth_accounts.map(account=>({json:{account,
 method: account.criado_nesta_execucao ? 'POST' : 'GET',
 url: 'https://supabase.multiverso360.com.br/auth/v1/admin/users' + (account.criado_nesta_execucao ? '' : '/' + account.usuario_id),
 body:{email:account.email,email_confirm:false,
 user_metadata:{nome:account.nome,papel:account.tipo,empresa_codigo:source.payload.empresa.codigo},
 app_metadata:{agenda24h_provisionamento:{versao:13,empresa_codigo:source.payload.empresa.codigo,chave:account.chave}}}
}}));

const validated = $('Validar JSON V2').first().json;
const requested = $('Preparar usuários Auth').all();
const responses = $input.all();
if (requested.length !== responses.length) throw new Error('Quantidade de respostas inesperada. Contas preservadas; conferir Auth antes de repetir.');
const sucesso=[], falhas=[];
for(let i=0;i<requested.length;i++) {
 const account=requested[i].json.account, r=responses[i].json, b=r.body ?? {};
 const status=Number(r.statusCode || 0);
 const u=b.user || b;
 if(r.error || status<200 || status>=300 || !/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(u.id||'') || String(u.email||'').toLowerCase()!==account.email || (!account.criado_nesta_execucao && u.id!==account.usuario_id)) {
   falhas.push({email:account.email,status,motivo:b.msg || b.message || b.error_description || r.error?.description || r.error?.message || JSON.stringify(b),codigo:b.error_code || b.code});
 } else sucesso.push({...account,usuario_id:u.id,email_confirmado:Boolean(u.email_confirmed_at || u.confirmed_at)});
}
if(falhas.length) return [{json:{falhou:true,motivo:JSON.stringify(falhas),usuarios_auth:sucesso}}];
const payload=JSON.parse(JSON.stringify(validated.payload));
for(const a of sucesso) {
 if(a.tipo==='administrador') payload.admin.usuario_id=a.usuario_id;
 else if(a.tipo==='profissional') payload.profissionais.find(p=>'profissional:'+p.chave===a.chave).usuario_id=a.usuario_id;
 else if(a.tipo==='recepcionista') payload.recepcionistas.find(p=>'recepcionista:'+p.chave===a.chave).usuario_id=a.usuario_id;
}
for(const p of payload.profissionais) if(p.eh_admin) p.usuario_id=payload.admin.usuario_id;
return [{json:{falhou:false,payload,payload_sql:JSON.stringify(payload),usuarios_auth:sucesso,redirect_to:validated.redirect_to}}];

const r=$input.first().json,b=r.body||{};
if(r.error || !(Number(r.statusCode)>=200 && Number(r.statusCode)<300) || !/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(b.empresa_id||'')) {
 throw new Error('Gravação pela API não confirmada. HTTP '+(r.statusCode||'sem resposta')+': '+(b.message||b.msg||r.error?.message||JSON.stringify(b))+' '+(b.details||'')+' '+(b.hint||'')+'. Contas Auth preservadas.');
}
return [{json:b}];

const c=$('Associar IDs do Auth').first().json;
const portal=String(c.redirect_to || 'https://consulta.multiverso360.com.br/definir-senha').trim();
const origem=portal.match(/^(https:\/\/[^\/?#\s]+)(?:[\/?#]|$)/i);
if(!origem) throw new Error('URL do portal inválida: informe um endereço HTTPS.');
const destinoConvite=origem[1]+'/definir-senha';
const destinoRecuperacao=origem[1]+'/redefinir-senha';
return c.usuarios_auth.map(a=>{
 const tipo=a.email_confirmado?'recuperacao':'convite';
 const destino=tipo==='convite'?destinoConvite:destinoRecuperacao;
 return {json:{email:a.email,tipo,body:{email:a.email},
  url:'https://supabase.multiverso360.com.br/auth/v1/'+(tipo==='convite'?'invite':'recover')+'?redirect_to='+encodeURIComponent(destino)
 }};
});

const requested=$('Preparar links de senha').all();
const responses=$input.all();
const falhas=[];
for(let i=0;i<requested.length;i++){
 const r=responses[i]?.json||{},b=r.body||{};
 if(r.error || !(Number(r.statusCode)>=200 && Number(r.statusCode)<300)) falhas.push({email:requested[i].json.email,tipo:requested[i].json.tipo,status:r.statusCode,motivo:b.msg||b.message||r.error?.message||JSON.stringify(b)});
}
const sucesso=requested.length>0 && responses.length===requested.length && falhas.length===0;
return [{json:{sucesso,empresa_gravada:true,empresa_id:$('Conferir resultado da empresa').first().json.empresa_id,conferencia:$('Conferir resultado da empresa').first().json.conferencia,envios_aceitos:requested.length-falhas.length,falhas_envio:falhas,mensagem:sucesso?'Provisionamento concluído. Todos os envios de e-mail de senha foram aceitos pelo Auth; confira o recebimento.':'Provisionamento incompleto: empresa gravada, mas o envio de todos os e-mails de senha não foi confirmado. Contas preservadas; confira falhas_envio antes de repetir.'}}];

const c=$('Associar IDs do Auth').first().json;
const r=$input.first().json;
const detalhe=c.falhou?c.motivo:JSON.stringify(r.error || r.body || r);
return [{json:{mensagem:'Provisionamento interrompido. '+detalhe+'. Nenhuma conta Auth foi excluída. Verifique o cadastro antes de repetir; use o mesmo empresa.codigo.',usuarios_auth_preservados:c.usuarios_auth||[]}}];
